// Generated by Cypress Author on 2026-11-24.
// Group the invalid-password authentication scenario.
describe('Swag Labs authentication', () => {
  // Define the single invalid-password login scenario.
  it('invalid password → stays on the login page and shows an error', () => {
    // Open the Swag Labs login page.
    cy.visit('/');

    // Enter the standard user's username.
    cy.get('[data-test="username"]').type('standard_user');
    // Enter an invalid password.
    cy.get('[data-test="password"]').type('wrong_password');
    // Submit the login form.
    cy.get('[data-test="login-button"]').click();

    // Confirm the browser remains on the login page.
    cy.location('pathname').should('eq', '/');
    // Confirm the login error is visible and contains the expected message.
    cy.get('[data-test="error"]').should('be.visible').and('contain', 'Username and password do not match any user in this service');
  });
});
